import{_ as e,o as d,c as o,a3 as a}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Vue 与 Nuxt AI API 索引","description":"速查本手册全栈主线（Vue 3 / Nuxt）实际讲过的 Chat composable、SSE、工具确认、上传与 SSR 边界入口及正文链接。","frontmatter":{"title":"Vue 与 Nuxt AI API 索引","description":"速查本手册全栈主线（Vue 3 / Nuxt）实际讲过的 Chat composable、SSE、工具确认、上传与 SSR 边界入口及正文链接。","outline":[2,3],"article":{"type":"index","structure":"index"}},"headers":[],"relativePath":"ts-ai/appendix/api-index/vue-nuxt-ai-api-index.md","filePath":"ts-ai/appendix/api-index/vue-nuxt-ai-api-index.md","lastUpdated":1786166505000}'),r={name:"ts-ai/appendix/api-index/vue-nuxt-ai-api-index.md"};function c(n,t,i,s,u,l){return d(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="vue-与-nuxt-ai-api-索引" tabindex="-1">Vue 与 Nuxt AI API 索引 <a class="header-anchor" href="#vue-与-nuxt-ai-api-索引" aria-label="Permalink to &quot;Vue 与 Nuxt AI API 索引&quot;">​</a></h1><blockquote><p>作者：cursor-grok-4.5</p></blockquote><p>本索引帮助你从 composable、事件类型或代理路径跳回 <code>docs/ts-ai/integration</code> 正文。<strong>Vue 3 + Nuxt 是全栈主线</strong>：默认消费 Nest 产品 SSE（<code>ProductSseEvent</code>）+ 自建 <code>useAgentChat</code>。<code>@ai-sdk/vue</code> 仅为可选适配，不替代产品契约。</p><h2 id="_1-索引范围与排除" tabindex="-1">1. 索引范围与排除 <a class="header-anchor" href="#_1-索引范围与排除" aria-label="Permalink to &quot;1. 索引范围与排除&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包含</th><th>排除</th></tr></thead><tbody><tr><td><code>vue-nuxt/</code> 主线 API：Chat composable、Run 状态、SSE 解析、工具确认、引用渲染、上传索引、SSR/密钥边界</td><td>React/Next 扩展轨（见 <a href="/ts-ai/appendix/api-index/react-next-api-index">React 与 Next.js 扩展 API 索引</a>）</td></tr><tr><td><code>interaction-protocols/</code> 与 <code>ai-interaction/</code> 中 Vue 必须认的产品事件、取消重连、错误体</td><td>Nest 服务端实现细节（见 <a href="/ts-ai/appendix/api-index/nestjs-api-index">NestJS API 索引</a>）</td></tr><tr><td>Nuxt/Nitro BFF（<code>/api/ai</code>）、假事件源与真 Nest 对接入口</td><td>把 AI SDK Data Stream 当作默认传输、在 SSR 挂起整次 Agent 流</td></tr></tbody></table><p>查 API 时：先认 <code>ProductSseEvent</code>，再进 composable；传输与重连跟协议篇，UI 组装跟 vue-nuxt 篇。</p><h2 id="_2-包与入口对象" tabindex="-1">2. 包与入口对象 <a class="header-anchor" href="#_2-包与入口对象" aria-label="Permalink to &quot;2. 包与入口对象&quot;">​</a></h2><table tabindex="0"><thead><tr><th>包 / 入口</th><th>本手册常用对象</th><th>正文</th></tr></thead><tbody><tr><td>Vue 3 + Nuxt 3 + TypeScript</td><td>默认前端栈；消费 Nest 产品 SSE</td><td><a href="/ts-ai/integration/vue-nuxt/">Vue/Nuxt 总览</a>、<a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a></td></tr><tr><td><code>~/composables/useAgentChat.ts</code></td><td>Chat 主入口：<code>send</code> / <code>cancel</code> / <code>cleanup</code> + refs</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Agent Chat Composable</a></td></tr><tr><td><code>~/types/sse-events</code>（或共享 <code>api-types</code>）</td><td><code>ProductSseEvent</code> 等类型唯一入口</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a>、<a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">消息·Run·工具事件</a></td></tr><tr><td><code>~/utils/apply-product-sse-event.ts</code></td><td>事件 → 状态纯函数（可单测）</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Composable</a>、<a href="/ts-ai/integration/vue-nuxt/message-run-state-management">状态管理</a></td></tr><tr><td><code>~/utils/parse-sse-stream.ts</code> / <code>create-nest-run-and-stream.ts</code></td><td>字节切帧；POST Run + GET stream</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">Nuxt↔Nest 对接</a>、<a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流事件解析</a></td></tr><tr><td><code>server/api/ai/runs/*</code></td><td>Nitro BFF：<code>sendProxy</code> / <code>defineEventHandler</code></td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a>、<a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a></td></tr><tr><td>浏览器原生</td><td><code>fetch</code> + <code>ReadableStream</code> + <code>AbortController</code> + <code>FormData</code>；<strong>不用</strong>裸 <code>EventSource</code> 挂 Bearer</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP/SSE</a>、<a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消与重连</a></td></tr><tr><td><code>marked</code> + <code>DOMPurify</code></td><td>completed 路径安全 Markdown</td><td><a href="/ts-ai/integration/vue-nuxt/streaming-message-rendering">流式渲染</a>、<a href="/ts-ai/integration/ai-interaction/markdown-code-citations">Markdown 与引用</a></td></tr><tr><td><code>@ai-sdk/vue</code> / <code>ai</code>（可选）</td><td><code>Chat</code> + transport / 旧 <code>useChat</code>；薄适配层</td><td><a href="/ts-ai/integration/vue-nuxt/ai-sdk-vue-integration">AI SDK Vue 集成</a></td></tr><tr><td>配置</td><td><code>runtimeConfig.nestApiBase</code>（仅服务端）、<code>public.aiProxyPrefix</code>（默认 <code>/api/ai</code>）</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a></td></tr></tbody></table><p>依赖方向：<strong>UI → protocol/state →（BFF）→ Nest</strong>。组件不直接持有 <code>AbortController</code>；Protocol 层不依赖 Vue ref。</p><h2 id="_3-核心-api-家族" tabindex="-1">3. 核心 API 家族 <a class="header-anchor" href="#_3-核心-api-家族" aria-label="Permalink to &quot;3. 核心 API 家族&quot;">​</a></h2><h3 id="_3-1-chat-composable-与-run-状态" tabindex="-1">3.1 Chat Composable 与 Run 状态 <a class="header-anchor" href="#_3-1-chat-composable-与-run-状态" aria-label="Permalink to &quot;3.1 Chat Composable 与 Run 状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>useAgentChat</code></td><td>Chat 核心：发送/流式/取消/清理</td><td>选项含 <code>createEventSource({ text, signal })</code>；默认可接假流；页面只绑返回值</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Agent Chat Composable</a></td></tr><tr><td><code>UseAgentChatOptions</code> / <code>UseAgentChatReturn</code></td><td>入参/出参契约</td><td>返回：<code>messages</code>、<code>runStatus</code>、<code>activeRunId</code>、<code>errorMessage</code>、<code>draft</code>、<code>busy</code>、<code>send</code>、<code>cancel</code>、<code>cleanup</code></td><td>同上</td></tr><tr><td><code>send</code> / <code>stream</code> / <code>cancel</code> / <code>cleanup</code></td><td>一次 Run 生命周期</td><td>非空 draft 且非 busy → <code>starting</code>；<code>AbortError</code> → <code>cancelled</code>；卸载调 <code>cleanup</code>（layout 长存活需路由钩子）</td><td>同上</td></tr><tr><td><code>busy</code></td><td>占用发送键</td><td><code>starting || streaming</code>；<strong>不要</strong>另造 <code>isLoading</code></td><td>同上</td></tr><tr><td><code>ChatMessage</code> / <code>RunStatus</code> / <code>AgentChatState</code></td><td>气泡与 Run UI 模型</td><td>Run：<code>idle|starting|streaming|completed|failed|cancelled</code>；消息 status：<code>pending|streaming|completed|failed</code></td><td><a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小 Chat UI</a>、<a href="/ts-ai/integration/vue-nuxt/message-run-state-management">状态管理</a></td></tr><tr><td><code>applyProductSseEvent</code> / <code>applyProductSseEventRich</code></td><td>事件 → 状态</td><td>delta <strong>追加</strong>；终态清 <code>activeRunId</code>；富版本带 <code>MessageStore</code> + <code>appliedKeys</code> 幂等</td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Composable</a>、<a href="/ts-ai/integration/vue-nuxt/message-run-state-management">状态管理</a></td></tr><tr><td><code>MessageStore</code> / <code>canStartRun</code></td><td>id-map 消息库与并发闸</td><td>对外仍 <code>ChatMessage[]</code>；默认<strong>禁双开</strong></td><td><a href="/ts-ai/integration/vue-nuxt/message-run-state-management">状态管理</a></td></tr><tr><td><code>fakeSupportTicketStream</code></td><td>假事件源</td><td><code>AsyncGenerator&lt;ProductSseEvent&gt;</code>，与真 SSE 同契约</td><td><a href="/ts-ai/integration/vue-nuxt/minimal-ai-chat-ui">最小 Chat UI</a></td></tr><tr><td><code>RunUiStatus</code>（交互设计）</td><td>产品态命名对照</td><td>含 <code>submitting</code> / <code>tool_pending</code>；与 Vue <code>starting</code>/<code>streaming</code> 对齐即可</td><td><a href="/ts-ai/integration/ai-interaction/streaming-state-feedback">流式状态反馈</a></td></tr></tbody></table><h3 id="_3-2-sse-消费、取消与重连" tabindex="-1">3.2 SSE 消费、取消与重连 <a class="header-anchor" href="#_3-2-sse-消费、取消与重连" aria-label="Permalink to &quot;3.2 SSE 消费、取消与重连&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>ProductSseEvent</code></td><td>统一产品 SSE 契约</td><td>字段与关联 ID 以协议篇为准；未知 type 不断开、不标失败</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">消息·Run·工具事件</a></td></tr><tr><td><code>POST</code> 创建 Run + <code>GET /v1/runs/:id/stream</code></td><td>默认传输</td><td><code>Accept: text/event-stream</code>；先创建再订阅</td><td><a href="/ts-ai/integration/interaction-protocols/http-sse-websocket">HTTP/SSE/WS</a>、<a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a></td></tr><tr><td><code>parseSseChunk</code> / <code>ParsedSseFrame</code> / <code>frameToStreamItem</code> / <code>iterateSseStream</code></td><td>半行缓冲 → 产品事件</td><td>空行定界；<code>: </code> 心跳跳过；绑定 <code>AbortSignal</code></td><td><a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流事件解析</a></td></tr><tr><td><code>parseSseStream</code> / <code>createNestRunAndStream</code> / <code>openRunStream</code></td><td>Vue/Nuxt 侧开流封装</td><td>注入 <code>useAgentChat.createEventSource</code>；带 Bearer 与可选 <code>Last-Event-ID</code></td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a>、<a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消与重连</a></td></tr><tr><td><code>cancelRun</code></td><td>双通道取消</td><td>本地 <code>abort</code> + <code>POST .../cancel</code>；409 已终态可当成功</td><td><a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消与重连</a></td></tr><tr><td><code>runStreamWithReconnect</code> / <code>shouldApplyEvent</code> / <code>reconcileRunStatus</code></td><td>重连、去重、REST 校对</td><td>指数退避；按 SSE <code>id</code> 幂等；<code>GET /v1/runs/:id</code> 防永远 spinning</td><td>同上</td></tr><tr><td>Nitro <code>sendProxy</code> SSE 代理</td><td>同域 BFF</td><td>禁缓冲：<code>X-Accel-Buffering: no</code></td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a></td></tr></tbody></table><h3 id="_3-3-工具确认与引用-ui" tabindex="-1">3.3 工具确认与引用 UI <a class="header-anchor" href="#_3-3-工具确认与引用-ui" aria-label="Permalink to &quot;3.3 工具确认与引用 UI&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>tool.confirmation_required</code></td><td>HITL 阻塞事件</td><td><strong>不是失败</strong>；Run 仍进行；禁用自动继续</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">协议事件</a>、<a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">工具确认</a></td></tr><tr><td><code>ToolCallCard</code> / <code>applyToolEvent</code> / <code>ToolProductEvent</code></td><td>工具卡片状态机</td><td>phase：<code>started|completed|confirmation_required|rejected</code>；按 <code>toolCallId</code></td><td><a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a></td></tr><tr><td><code>postToolDecision</code> / <code>ToolDecision</code></td><td>批准/拒绝 REST</td><td><code>POST /v1/runs/{runId}/tool-calls/{toolCallId}/decision</code>；<code>approve|reject</code> + <code>Idempotency-Key</code>（概念篇亦见 <code>tool-confirmations</code> 路径）</td><td><a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具调用 UI</a>、<a href="/ts-ai/integration/ai-interaction/tool-confirmation-human-loop">HITL</a></td></tr><tr><td><code>citation.added</code></td><td>结构化引用</td><td>挂 <code>messageId</code>；按 <code>citationId</code> 幂等；不靠模型 <code>[^1]</code> 当真相</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">协议</a>、<a href="/ts-ai/integration/ai-interaction/markdown-code-citations">Markdown 与引用</a></td></tr><tr><td><code>renderChatMarkdown</code> / <code>patchStreamingMarkdown</code></td><td>安全 Markdown</td><td>streaming：转义+<code>&lt;br&gt;</code>；completed：<code>marked</code>+<code>DOMPurify</code>；禁 raw HTML</td><td><a href="/ts-ai/integration/vue-nuxt/streaming-message-rendering">流式渲染</a></td></tr><tr><td><code>useChatScroll</code> / <code>useThrottledContent</code></td><td>贴底与渲染节流</td><td>只节流渲染，不节流 <code>applyEvent</code></td><td>同上</td></tr><tr><td>UI 组件族</td><td><code>ChatMessageList</code> / <code>ChatMarkdownBubble</code> / <code>ChatComposer</code> / <code>ChatRunStatusBar</code></td><td>组件不直接 fetch Nest</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a>、<a href="/ts-ai/integration/vue-nuxt/streaming-message-rendering">流式渲染</a></td></tr></tbody></table><h3 id="_3-4-上传与索引状态" tabindex="-1">3.4 上传与索引状态 <a class="header-anchor" href="#_3-4-上传与索引状态" aria-label="Permalink to &quot;3.4 上传与索引状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>FileIndexStatus</code> / <code>mapServerFileStatus</code></td><td>索引产品态</td><td>UI：<code>pending|indexing|ready|failed</code>；服务端 <code>processing</code> → <code>indexing</code></td><td><a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">上传与索引状态</a></td></tr><tr><td><code>UploadedFileItem</code> / <code>createOptimisticItem</code></td><td>上传列项与乐观 UI</td><td><code>local:</code> uuid；成功后替换 <code>fileId</code> 并 revoke 预览 URL</td><td>同上</td></tr><tr><td><code>uploadChatFile</code> / <code>FileUploadResponse</code></td><td><code>POST /v1/files</code></td><td>multipart；勿手设 <code>Content-Type</code>；<code>purpose: rag|attachment</code></td><td>同上；<a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权与文件协议</a></td></tr><tr><td><code>file.index.updated</code> / <code>applyFileIndexUpdated</code></td><td>索引进度事件</td><td><strong>可无 runId</strong>；按 <code>fileId</code>；不改气泡正文</td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">协议</a>、<a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">上传篇</a></td></tr><tr><td><code>useFileIndexing</code> / <code>pollFileUntilTerminal</code> / <code>reindexFile</code></td><td>面板 composable 与回退</td><td>无 SSE 时轮询 <code>GET /v1/files/:id</code>；失败优先 <code>POST .../reindex</code></td><td><a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">上传与索引状态</a></td></tr><tr><td>createRun 传 <code>fileIds</code></td><td>引用就绪附件</td><td>仅 <code>ready</code> 可进 <code>fileIds</code></td><td>同上</td></tr></tbody></table><h3 id="_3-5-ssr-密钥边界-按需" tabindex="-1">3.5 SSR / 密钥边界（按需） <a class="header-anchor" href="#_3-5-ssr-密钥边界-按需" aria-label="Permalink to &quot;3.5 SSR / 密钥边界（按需）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>API</th><th>用途</th><th>关键点</th><th>正文</th></tr></thead><tbody><tr><td><code>ClientOnly</code> Chat 岛</td><td>流式面板 CSR</td><td>SSE/滚动/Abort <strong>不参与</strong>水合</td><td><a href="/ts-ai/integration/vue-nuxt/ssr-hydration-client-state">SSR 与客户端状态</a></td></tr><tr><td>SSR vs CSR 拆分</td><td>边界</td><td>SSR：Thread 列表/壳/可选历史快照；CSR：send/SSE/工具/上传</td><td>同上</td></tr><tr><td><code>useState</code> / <code>useAsyncData</code></td><td>首屏可注入缓存</td><td>Thread 列表；历史仅 completed；<strong>勿</strong> SSR 流式 messages</td><td>同上</td></tr><tr><td><code>useChatDraft</code> / <code>definePageMeta({ ssr: false })</code> / <code>.client.ts</code></td><td>草稿与整页关 SSR</td><td>草稿仅 <code>onMounted</code> 读写；禁止通用插件顶层开 SSE</td><td>同上</td></tr><tr><td>密钥边界</td><td>安全</td><td>模型 Key、长期 JWT <strong>永不</strong> <code>runtimeConfig.public</code>；token 内存/会话下发；Nest 基址仅服务端</td><td><a href="/ts-ai/integration/vue-nuxt/nuxt-ai-project-structure">项目结构</a>、<a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a>、<a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权协议</a></td></tr></tbody></table><h2 id="_4-事件、错误与配置速查" tabindex="-1">4. 事件、错误与配置速查 <a class="header-anchor" href="#_4-事件、错误与配置速查" aria-label="Permalink to &quot;4. 事件、错误与配置速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>主题</th><th>关键项</th><th>放哪里处理</th><th>正文</th></tr></thead><tbody><tr><td>Run / 消息事件</td><td><code>run.started</code>、<code>message.delta</code>、<code>message.completed</code>、<code>run.completed</code>/<code>failed</code>/<code>cancelled</code></td><td><code>applyProductSseEvent*</code>；delta 按稳定 <code>messageId</code> <strong>追加</strong></td><td><a href="/ts-ai/integration/interaction-protocols/message-run-tool-call-events">协议事件</a></td></tr><tr><td>工具 / 引用 / 文件</td><td><code>tool.started</code>/<code>completed</code>/<code>failed</code>、<code>tool.confirmation_required</code>、<code>citation.added</code>、<code>file.index.updated</code></td><td>工具与引用独立卡片；文件列表按 <code>fileId</code></td><td>同上；<a href="/ts-ai/integration/vue-nuxt/tool-call-ui">工具 UI</a>、<a href="/ts-ai/integration/vue-nuxt/file-upload-indexing-state">上传</a></td></tr><tr><td>SSE 帧</td><td><code>id:</code> / <code>event:</code> / <code>data:</code> / <code>: ping</code></td><td>解析层；心跳非产品事件；生产流须单调 <code>id:</code></td><td><a href="/ts-ai/integration/interaction-protocols/stream-event-parsing">流事件解析</a>、<a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消与重连</a></td></tr><tr><td>HTTP 错误体</td><td><code>ApiErrorBody</code>：<code>code</code>/<code>message</code>/<code>details?</code>/<code>requestId?</code>/<code>retryable?</code></td><td><code>readApiError</code> → <code>mapErrorToUi</code>；按 code 分支，勿一律 Toast 重试</td><td><a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权·文件·错误</a></td></tr><tr><td>常见错误码</td><td><code>UNAUTHENTICATED</code>、<code>FORBIDDEN</code>、<code>VALIDATION_ERROR</code>、<code>RATE_LIMITED</code>、<code>NOT_FOUND</code>、<code>CONFLICT</code>、<code>RUN_FAILED</code>、<code>STREAM_RECONNECT_EXHAUSTED</code>、上传类 413/415</td><td>UI：login / retry / form / none</td><td>同上；<a href="/ts-ai/integration/interaction-protocols/cancellation-reconnection-deduplication">取消篇</a></td></tr><tr><td>Composable 错误规则</td><td>取消不进 <code>errorMessage</code>；网络/<code>run.failed</code> 进</td><td><code>useAgentChat</code></td><td><a href="/ts-ai/integration/vue-nuxt/agent-chat-composable">Composable</a></td></tr><tr><td>请求头 / 配置</td><td><code>Authorization: Bearer</code>、<code>Idempotency-Key</code>、<code>Last-Event-ID</code>、Cookie+CSRF、代理前缀 <code>/api/ai</code></td><td>REST/SSE/工具决策/重连</td><td><a href="/ts-ai/integration/interaction-protocols/auth-files-error-protocols">鉴权协议</a>、<a href="/ts-ai/integration/vue-nuxt/nuxt-nestjs-integration">对接</a></td></tr></tbody></table><p>关联 ID：<code>threadId</code>、<code>runId</code>、<code>messageId</code>、<code>toolCallId</code>、<code>citationId</code>、<code>fileId</code>。</p><h2 id="_5-关联章节" tabindex="-1">5. 关联章节 <a class="header-anchor" href="#_5-关联章节" aria-label="Permalink to &quot;5. 关联章节&quot;">​</a></h2><table tabindex="0"><thead><tr><th>章节</th><th>用本索引时怎么用</th></tr></thead><tbody><tr><td><a href="/ts-ai/integration/">全栈集成总览</a></td><td>协议 → AI 交互 → Vue/Nuxt 主线顺序</td></tr><tr><td><a href="/ts-ai/integration/interaction-protocols/">交互协议</a></td><td>事件契约、SSE 解析、取消重连、鉴权错误</td></tr><tr><td><a href="/ts-ai/integration/ai-interaction/">AI 交互体验</a></td><td>信息架构、流式反馈、HITL、Markdown/引用</td></tr><tr><td><a href="/ts-ai/integration/vue-nuxt/">Vue / Nuxt</a></td><td>composable、状态、渲染、对接、上传、SSR</td></tr><tr><td><a href="/ts-ai/integration/vue-nuxt/complete-ai-chat-project">AI Chat 拼装验收清单</a></td><td>主线拼装勾选，非完整仓库</td></tr><tr><td><a href="/ts-ai/integration/assembly/assembly-recipes-checklist">全栈集成组装配方</a></td><td>按配方勾选能力</td></tr><tr><td><a href="/ts-ai/appendix/api-index/nestjs-api-index">NestJS API 索引</a></td><td>后端 REST/SSE/上传入口</td></tr><tr><td><a href="/ts-ai/appendix/references/official-resources">官方资料索引</a></td><td>本索引未收录的 API，以官方文档为准</td></tr><tr><td><a href="/ts-ai/appendix/api-index/react-next-api-index">React 与 Next.js 扩展 API 索引</a></td><td>非主线对照；事件契约应共享</td></tr><tr><td><a href="/ts-ai/appendix/learning/knowledge-checklist">知识点清单</a></td><td>行为验收勾选，不代替本索引的 API 跳转</td></tr></tbody></table>',25)])])}const g=e(r,[["render",c]]);export{p as __pageData,g as default};
